import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for p in fw.get('topLevelPackages', []):
                key = (p['id'], tfm)
                pkgs[key] = p['resolvedVersion']
        result[name] = pkgs
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for key in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(key)
        av = ap.get(key)
        pkg, tfm = key
        if bv != av:
            changes.append((proj, pkg, tfm, bv, av))
        else:
            unchanged.append((proj, pkg, tfm, bv))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]} | {c[1]} ({c[2]}): {c[3]} -> {c[4]}')
print(f'\n=== UNCHANGED: {len(unchanged)} entries ===')
"

