import sys, json
data = json.load(sys.stdin)
with open('after-cpm-packages.json', 'w') as f:
    json.dump(data, f, indent=2)

# Compare
def extract(d):
    result = {}
    for proj in d.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for p in fw.get('topLevelPackages', []):
                pkgs[(p['id'], tfm)] = p['resolvedVersion']
        result[name] = pkgs
    return result

a = extract(data)
print('After-CPM packages per project:')
for proj in sorted(a):
    print(f'  {proj}:')
    for (pkg, tfm), ver in sorted(a[proj].items()):
        print(f'    {pkg} ({tfm}): {ver}')
"

